  N["factors-fractions-exponents-skill-01"] = {"obj": "use divisibility rules to find factors", "idea": "A number is divisible by another if the quotient is a whole number. Divisibility rules let you check 2, 3, 5, 9 and 10 without dividing.", "voc": [["factor", "A whole number that divides another whole number with no remainder."], ["divisible", "Able to be divided with no remainder."]], "watch": "Using the digit-sum rule for 2 or 5, which depend only on the last digit.", "frame": "___ is divisible by ___ because ___.", "cards": [{"h": "Divisibility rules", "big": "Test 4,212.", "steps": ["Last digit 2 is even, so divisible by {{2}}.", "Digit sum 4 + 2 + 1 + 2 = {{9}}, so divisible by 3 and by {{9}}.", "Last digit is not 0 or 5, so {{not}} divisible by 5."]}], "review": true};
  N["factors-fractions-exponents-skill-02"] = {"obj": "write and evaluate powers, including negative bases", "idea": "An exponent tells how many times the base is used as a factor. Parentheses decide whether a negative sign is part of the base.", "voc": [["base", "The number used as a repeated factor."], ["exponent", "The number of times the base is used as a factor."], ["power", "An expression with a base and an exponent, or its value."]], "watch": "Multiplying the base by the exponent (⟨3^4 = 12⟩) or ignoring parentheses (⟨-2^4⟩ vs ⟨(-2)^4⟩).", "frame": "The base is ___ and it is used ___ times, so the value is ___.", "cards": [{"h": "Powers", "big": "The exponent counts the factors.", "steps": ["⟨3^4 = 3 \\cdot 3 \\cdot 3 \\cdot 3 = {{81}}⟩", "⟨(-2)^4 = {{16}}⟩", "⟨-2^4 = -(2^4) = {{-16}}⟩"]}], "review": true};
  N["factors-fractions-exponents-skill-03"] = {"obj": "write prime factorizations and find the greatest common factor", "idea": "Every whole number greater than 1 is a product of primes in exactly one way. The GCF is the product of the prime factors the numbers share.", "voc": [["prime number", "A whole number greater than 1 with exactly two factors, 1 and itself."], ["prime factorization", "A number written as a product of prime numbers."], ["greatest common factor (GCF)", "The greatest number that is a factor of each number."]], "watch": "Listing 1 or composite numbers (such as 4) in a prime factorization.", "frame": "Both numbers share the prime factors ___, so the GCF is ___.", "cards": [{"h": "Factor trees", "big": "Split until every branch ends in a prime.", "steps": ["⟨72 = 2^3 \\cdot 3^{{2}}⟩", "⟨60 = 2^2 \\cdot 3 \\cdot {{5}}⟩", "GCF: ⟨2^2 \\cdot 3 = {{12}}⟩"]}], "review": true};
  N["factors-fractions-exponents-skill-04"] = {"obj": "write fractions in simplest form using the GCF", "idea": "Dividing the numerator and denominator by the same nonzero number gives an equivalent fraction. Dividing by the GCF gives simplest form in one step.", "voc": [["equivalent fractions", "Fractions that name the same number."], ["simplest form", "A fraction whose numerator and denominator have no common factor except 1."]], "watch": "Subtracting the same number from the numerator and denominator.", "frame": "The GCF of ___ and ___ is ___, so the fraction simplifies to ___.", "cards": [{"h": "Divide by the GCF", "big": "Simplify ⟨\\frac{36}{48}⟩.", "steps": ["GCF of 36 and 48: {{12}}", "⟨\\frac{36 \\div 12}{48 \\div 12} = {{\\frac{3}{4}}}⟩", "Check: 3 and 4 share no factor except {{1}}."]}], "review": true};
  N["factors-fractions-exponents-skill-05"] = {"obj": "identify rational numbers and write them as fractions", "idea": "A rational number can be written as ⟨\\frac{a}{b}⟩ with integers a and b ≠ 0. Integers, terminating decimals and repeating decimals are all rational.", "voc": [["rational number", "A number that can be written as a quotient of two integers with a nonzero divisor."], ["terminating decimal", "A decimal that ends, such as 0.375."], ["repeating decimal", "A decimal with a digit or group of digits that repeats forever, such as 0.333…."]], "watch": "Thinking negative numbers or repeating decimals are not rational.", "frame": "___ is rational because it equals ___.", "cards": [{"h": "Write as a fraction", "big": "Every one of these is rational.", "steps": ["⟨-7 = \\frac{-7}{{{1}}}⟩", "⟨0.375 = \\frac{375}{1000} = {{\\frac{3}{8}}}⟩", "⟨0.\\overline{3} = {{\\frac{1}{3}}}⟩"]}]};
  N["factors-fractions-exponents-skill-06"] = {"obj": "classify numbers as rational or irrational and locate irrational numbers on a number line", "idea": "An irrational number cannot be written as a fraction; its decimal never ends or repeats. Square roots of non-perfect squares and π are irrational, and we approximate them.", "voc": [["irrational number", "A number whose decimal neither terminates nor repeats, such as ⟨\\sqrt{2}⟩ or π."], ["perfect square", "The square of an integer, such as 49."], ["real numbers", "All rational and irrational numbers."]], "watch": "Calling every square root irrational; ⟨\\sqrt{49}⟩ = 7 is rational.", "frame": "___ is irrational because ___. It is between ___ and ___.", "cards": [{"h": "Estimate ⟨\\sqrt{50}⟩", "big": "Find the perfect squares on each side.", "steps": ["⟨49 < 50 < 64⟩, so ⟨7 < \\sqrt{50} < {{8}}⟩", "50 is close to 49, so ⟨\\sqrt{50} \\approx {{7.1}}⟩", "⟨\\sqrt{50}⟩ is {{irrational}}; ⟨\\sqrt{49}⟩ is rational."]}]};
  N["factors-fractions-exponents-skill-07"] = {"obj": "multiply powers with the same base", "idea": "When you multiply powers with the same base, you are counting all the factors, so add the exponents: ⟨a^m \\cdot a^n = a^{m+n}⟩. A zero exponent gives 1 and a negative exponent gives a reciprocal.", "voc": [["product of powers", "⟨a^m \\cdot a^n = a^{m+n}⟩ for the same base a."], ["zero exponent", "⟨a^0 = 1⟩ for a ≠ 0."], ["negative exponent", "⟨a^{-n} = \\frac{1}{a^n}⟩."]], "watch": "Multiplying the exponents (⟨x^3 \\cdot x^4 = x^{12}⟩) or multiplying the bases (⟨2^3 \\cdot 2^4 = 4^7⟩).", "frame": "The bases are the same, so I ___ the exponents.", "cards": [{"h": "Add the exponents", "big": "Same base: keep it and add the exponents.", "steps": ["⟨x^3 \\cdot x^4 = x^{{{7}}}⟩", "⟨2^5 \\cdot 2^{-2} = 2^{{3}} = 8⟩", "⟨3a^2 \\cdot 4a^5 = {{12a^7}}⟩"]}]};
  N["factors-fractions-exponents-skill-08"] = {"obj": "divide powers with the same base and use zero and negative exponents", "idea": "Dividing cancels common factors, so subtract the exponents: ⟨\\frac{a^m}{a^n} = a^{m-n}⟩. This is why ⟨a^0 = 1⟩ and ⟨a^{-n} = \\frac{1}{a^n}⟩.", "voc": [["quotient of powers", "⟨\\frac{a^m}{a^n} = a^{m-n}⟩ for the same nonzero base a."], ["reciprocal", "One divided by a number; ⟨\\frac{1}{a^n}⟩ is the reciprocal of ⟨a^n⟩."]], "watch": "Dividing the exponents, or writing a negative exponent as a negative number (⟨2^{-3} = -8⟩).", "frame": "I subtract ___ − ___ to get the exponent ___.", "cards": [{"h": "Subtract the exponents", "big": "Same base: keep it and subtract.", "steps": ["⟨\\frac{y^9}{y^4} = y^{{{5}}}⟩", "⟨\\frac{5^3}{5^3} = 5^0 = {{1}}⟩", "⟨2^{-3} = \\frac{1}{2^3} = {{\\frac{1}{8}}}⟩"]}]};
  N["factors-fractions-exponents-skill-09"] = {"obj": "write numbers in scientific notation and compute with them", "idea": "Scientific notation writes a number as ⟨a \\times 10^n⟩ with ⟨1 \\le a < 10⟩. The exponent counts how many places the decimal point moves.", "voc": [["scientific notation", "A number written as ⟨a \\times 10^n⟩, where ⟨1 \\le a < 10⟩ and n is an integer."], ["standard form", "A number written with all its digits, such as 4,500,000."]], "watch": "Writing a first factor of 10 or more (⟨45 \\times 10^5⟩), or using a positive exponent for a small number.", "frame": "I moved the decimal point ___ places to the ___, so the exponent is ___.", "cards": [{"h": "Big and small", "big": "Make a number from 1 to 10, then count the places.", "steps": ["⟨4{,}500{,}000 = 4.5 \\times 10^{{{6}}}⟩", "⟨0.00032 = 3.2 \\times 10^{{{-4}}}⟩", "⟨(2 \\times 10^3)(4 \\times 10^5) = {{8 \\times 10^8}}⟩"]}]};
  N["factors-fractions-exponents-skill-10"] = {"obj": "find cube roots and solve equations of the form ⟨x^3 = p⟩", "idea": "The cube root undoes cubing: ⟨\\sqrt[3]{p}⟩ is the number whose cube is p. Cube roots of negative numbers are negative.", "voc": [["cube root", "A number that, used as a factor three times, gives the original number."], ["perfect cube", "The cube of an integer, such as 27 or −8."]], "watch": "Dividing by 3 instead of taking the cube root (⟨\\sqrt[3]{27} = 9⟩).", "frame": "___ cubed is ___, so the cube root of ___ is ___.", "cards": [{"h": "Undo cubing", "big": "Ask: what number times itself three times?", "steps": ["⟨\\sqrt[3]{64} = {{4}}⟩", "⟨\\sqrt[3]{-125} = {{-5}}⟩", "⟨x^3 = 343⟩ → ⟨x = {{7}}⟩"]}]};
  /* ---------- operations-fractions ---------- */
  N["operations-fractions-skill-01"] = {"obj": "compare and order fractions, decimals and integers", "idea": "Write the numbers in the same form (decimals or common denominators), then compare. On a number line, the greater number is to the right.", "voc": [["least common denominator", "The least common multiple of the denominators."], ["rational number", "A number that can be written as a quotient of integers."]], "watch": "Thinking ⟨-\\frac{3}{4} > -\\frac{2}{3}⟩ because 3/4 > 2/3; for negatives, the order flips.", "frame": "In decimal form ___ is ___, so it is ___ than ___.", "cards": [{"h": "Same form, then compare", "big": "Order ⟨-\\frac{3}{4}, -0.7, -\\frac{2}{3}⟩ from least to greatest.", "steps": ["Decimals: −0.75, −0.7, ⟨-0.\\overline{6}⟩", "Least is {{−3/4}}, greatest is {{−2/3}}.", "Order: ⟨-\\frac{3}{4}, -0.7, {{-\\frac{2}{3}}}⟩"]}]};
  N["operations-fractions-skill-02"] = {"obj": "convert between fractions and decimals, including repeating decimals", "idea": "Divide the numerator by the denominator. The decimal terminates if the simplified denominator has only 2s and 5s as prime factors; otherwise it repeats.", "voc": [["terminating decimal", "A decimal that ends."], ["repeating decimal", "A decimal with a repeating block, shown with a bar, such as ⟨0.8\\overline{3}⟩."]], "watch": "Writing ⟨\\frac{5}{6}⟩ as 0.83 and treating it as exact.", "frame": "___ ÷ ___ = ___, which ___.", "cards": [{"h": "Divide", "big": "The denominator decides: terminate or repeat.", "steps": ["⟨\\frac{3}{8} = {{0.375}}⟩ (terminates)", "⟨\\frac{5}{6} = {{0.8\\overline{3}}}⟩ (repeats)", "⟨0.45 = \\frac{45}{100} = {{\\frac{9}{20}}}⟩"]}]};
  N["operations-fractions-skill-03"] = {"obj": "add and subtract fractions and mixed numbers with unlike denominators, including negatives", "idea": "Rewrite with a common denominator, then add or subtract the numerators. The integer sign rules still apply.", "voc": [["common denominator", "A shared multiple of the denominators."], ["mixed number", "A whole number and a fraction, such as ⟨2\\frac{1}{3}⟩."]], "watch": "Adding denominators (⟨\\frac{1}{2} + \\frac{1}{3} = \\frac{2}{5}⟩).", "frame": "The common denominator is ___, so I rewrite ___ as ___.", "cards": [{"h": "Common denominators", "big": "Compute ⟨\\frac{2}{3} - \\frac{5}{4}⟩.", "steps": ["⟨= \\frac{8}{12} - \\frac{{{15}}}{12}⟩", "⟨= {{-\\frac{7}{12}}}⟩", "⟨2\\frac{1}{2} + 1\\frac{2}{3} = \\frac{15}{6} + \\frac{10}{6} = {{4\\frac{1}{6}}}⟩"]}]};
  N["operations-fractions-skill-04"] = {"obj": "multiply and divide fractions and mixed numbers, including negatives", "idea": "Multiply numerators and denominators. To divide, multiply by the reciprocal of the divisor. Write mixed numbers as fractions first.", "voc": [["reciprocal", "Two numbers whose product is 1, such as ⟨\\frac{3}{4}⟩ and ⟨\\frac{4}{3}⟩."], ["improper fraction", "A fraction whose numerator is greater than or equal to its denominator."]], "watch": "Taking the reciprocal of the first fraction instead of the divisor.", "frame": "Dividing by ___ is the same as multiplying by ___.", "cards": [{"h": "Multiply by the reciprocal", "big": "Compute ⟨-\\frac{3}{4} \\div 1\\frac{1}{2}⟩.", "steps": ["⟨= -\\frac{3}{4} \\div \\frac{3}{2}⟩", "⟨= -\\frac{3}{4} \\cdot {{\\frac{2}{3}}}⟩", "⟨= {{-\\frac{1}{2}}}⟩"]}]};
  N["operations-fractions-skill-05"] = {"obj": "convert customary units of length, weight and capacity", "idea": "Multiply by a conversion factor written as a fraction equal to 1, so the old unit cancels. Converting to a smaller unit gives a larger number.", "voc": [["conversion factor", "A ratio of equal measures, such as ⟨\\frac{12\\text{ in.}}{1\\text{ ft}}⟩."], ["customary units", "Inches, feet, yards, miles; ounces, pounds; cups, pints, quarts, gallons."]], "watch": "Multiplying when converting to a larger unit (36 in. = 432 ft).", "frame": "I multiply by ___ so that ___ cancels.", "cards": [{"h": "Unit fractions equal to 1", "big": "1 ft = 12 in., 1 lb = 16 oz, 1 gal = 4 qt.", "steps": ["⟨5\\text{ ft} \\cdot \\frac{12\\text{ in.}}{1\\text{ ft}} = {{60}}\\text{ in.}⟩", "⟨40\\text{ oz} = \\frac{40}{16} = {{2\\frac{1}{2}}}\\text{ lb}⟩", "⟨3\\text{ gal} = {{12}}\\text{ qt}⟩"]}], "review": true};
  N["operations-fractions-skill-06"] = {"obj": "solve one-step equations with fractions by adding or subtracting", "idea": "Use the inverse operation on both sides, then add or subtract fractions with a common denominator.", "voc": [["inverse operations", "Operations that undo each other."], ["common denominator", "A shared multiple of the denominators."]], "watch": "Subtracting the fractions in the wrong order when the variable is subtracted (⟨\\frac{3}{4} - x⟩).", "frame": "To undo ___, I ___ on both sides.", "cards": [{"h": "Undo with fractions", "big": "Solve ⟨x + \\frac{2}{3} = \\frac{1}{4}⟩.", "steps": ["⟨x = \\frac{1}{4} - \\frac{2}{3}⟩", "⟨x = \\frac{3}{12} - \\frac{8}{12}⟩", "⟨x = {{-\\frac{5}{12}}}⟩"]}]};
  N["operations-fractions-skill-07"] = {"obj": "solve one-step equations by multiplying by a reciprocal", "idea": "To undo multiplying by a fraction, multiply both sides by its reciprocal; the product of a number and its reciprocal is 1.", "voc": [["reciprocal", "The number you multiply by to get 1."], ["multiplicative inverse", "Another name for the reciprocal."]], "watch": "Multiplying one side only, or dividing by the fraction’s numerator alone.", "frame": "I multiply both sides by ___, the reciprocal of ___.", "cards": [{"h": "Multiply by the reciprocal", "big": "Solve ⟨\\frac{3}{5}x = -12⟩.", "steps": ["⟨\\frac{5}{3} \\cdot \\frac{3}{5}x = \\frac{5}{3}(-12)⟩", "⟨x = {{-20}}⟩", "Check: ⟨\\frac{3}{5}(-20) = {{-12}}⟩"]}]};
  N["operations-fractions-skill-08"] = {"obj": "raise products and quotients to a power", "idea": "A power of a product or quotient applies to every factor: ⟨(ab)^n = a^n b^n⟩ and ⟨\\left(\\frac{a}{b}\\right)^n = \\frac{a^n}{b^n}⟩. A power of a power multiplies the exponents.", "voc": [["power of a product", "⟨(ab)^n = a^n b^n⟩."], ["power of a power", "⟨(a^m)^n = a^{mn}⟩."]], "watch": "Raising only one factor to the power (⟨(3x)^2 = 3x^2⟩).", "frame": "The exponent applies to ___ and to ___.", "cards": [{"h": "Every factor", "big": "Raise each factor to the power.", "steps": ["⟨(3x)^2 = {{9x^2}}⟩", "⟨(2a^3)^4 = 16a^{{{12}}}⟩", "⟨\\left(\\frac{2}{5}\\right)^3 = {{\\frac{8}{125}}}⟩"]}]};
  /* ---------- ratios-proportions-percentages ---------- */
  N["ratios-proportions-percentages-skill-01"] = {"obj": "write ratios and find unit rates, including rates with fractions", "idea": "A unit rate compares a quantity to one unit of another. Divide the first quantity by the second, even when both are fractions.", "voc": [["ratio", "A comparison of two quantities by division."], ["rate", "A ratio of quantities with different units."], ["unit rate", "A rate for one unit, such as 3 miles per 1 hour."]], "watch": "Dividing in the wrong order (hours per mile instead of miles per hour).", "frame": "I divide ___ by ___ to find ___ per ___.", "cards": [{"h": "Unit rate with fractions", "big": "Ana walks ⟨\\frac{1}{2}⟩ mile in ⟨\\frac{1}{4}⟩ hour.", "steps": ["⟨\\frac{1}{2} \\div \\frac{1}{4} = \\frac{1}{2} \\cdot {{4}}⟩", "⟨= {{2}}⟩ miles per hour", "$4.50 for 6 apples: {{$0.75}} per apple"]}]};
  N["ratios-proportions-percentages-skill-02"] = {"obj": "decide whether two ratios form a proportion and solve proportions", "idea": "Two ratios are proportional if they are equivalent; their cross products are equal. Solve a proportion by scaling or by cross products.", "voc": [["proportion", "An equation stating that two ratios are equal."], ["cross products", "In ⟨\\frac{a}{b} = \\frac{c}{d}⟩, the products ad and bc."]], "watch": "Setting up the second ratio in a different order (miles/hours = hours/miles).", "frame": "I set up ___ = ___ because both ratios compare ___ to ___.", "cards": [{"h": "Solve a proportion", "big": "3 notebooks cost $7.50. How much for 8?", "steps": ["⟨\\frac{3}{7.50} = \\frac{8}{x}⟩", "⟨3x = {{60}}⟩", "⟨x = {{20}}⟩ dollars"]}]};
  N["ratios-proportions-percentages-skill-03"] = {"obj": "use scale factors with similar figures and scale drawings, and describe dilations", "idea": "Similar figures have equal angles and proportional sides. A scale factor multiplies every length; a dilation by k from the origin multiplies each coordinate by k.", "voc": [["scale factor", "The number each length is multiplied by to get the new figure."], ["scale drawing", "A drawing in which every length is in the same ratio to the real object."], ["dilation", "A transformation that enlarges or reduces a figure by a scale factor."]], "watch": "Multiplying areas by the scale factor; area is multiplied by the scale factor squared.", "frame": "The scale is ___, so ___ in the drawing is ___ in real life.", "cards": [{"h": "Use the scale", "big": "Map scale 1 in. : 25 mi.", "steps": ["3.5 in. on the map → ⟨3.5 \\times 25 = {{87.5}}⟩ mi", "A dilation by 2 maps (3, −1) to ({{6}}, {{−2}}).", "Lengths ×2, so area × {{4}}."]}]};
  N["ratios-proportions-percentages-skill-04"] = {"obj": "find theoretical probabilities and describe likelihood from 0 to 1", "idea": "With equally likely outcomes, P(event) = favorable outcomes ÷ total outcomes. Probabilities run from 0 (impossible) to 1 (certain), and P(not A) = 1 − P(A).", "voc": [["outcome", "One possible result of an experiment."], ["event", "A set of outcomes."], ["complement", "All outcomes not in the event; P(not A) = 1 − P(A)."]], "watch": "Counting favorable outcomes against unfavorable ones (odds) instead of the total.", "frame": "There are ___ favorable outcomes out of ___, so P = ___.", "cards": [{"h": "Count, then divide", "big": "A bag has 3 red, 5 blue and 2 green marbles.", "steps": ["P(blue) = ⟨\\frac{5}{10} = {{\\frac{1}{2}}}⟩", "P(not green) = ⟨1 - \\frac{2}{10} = {{\\frac{4}{5}}}⟩", "P(yellow) = {{0}}: impossible"]}]};
  N["ratios-proportions-percentages-skill-05"] = {"obj": "convert among fractions, decimals and percents", "idea": "Percent means per hundred. Write a fraction with denominator 100, or divide to get a decimal and move the decimal point two places.", "voc": [["percent", "A ratio that compares a number to 100."], ["equivalent forms", "The same number written as a fraction, decimal and percent."]], "watch": "Moving the decimal point the wrong way (0.4 = 0.4%).", "frame": "___ as a decimal is ___, which is ___%.", "cards": [{"h": "Three forms", "big": "Fraction ↔ decimal ↔ percent.", "steps": ["⟨\\frac{3}{8} = 0.375 = {{37.5}}\\%⟩", "⟨140\\% = {{1.4}} = \\frac{7}{5}⟩", "⟨0.4\\% = {{0.004}}⟩"]}]};
  N["ratios-proportions-percentages-skill-06"] = {"obj": "solve percent problems with proportions", "idea": "A percent proportion compares the part to the whole: ⟨\\frac{\\text{part}}{\\text{whole}} = \\frac{p}{100}⟩. Decide which of the three numbers is missing.", "voc": [["part", "The amount that is a percent of the whole."], ["whole", "The total amount, 100%."]], "watch": "Putting the part in the denominator when it follows the word “of”: “of” names the whole.", "frame": "___ is the whole because ___, so I write ___.", "cards": [{"h": "Part over whole", "big": "18 is what percent of 75?", "steps": ["⟨\\frac{18}{75} = \\frac{p}{100}⟩", "⟨75p = {{1800}}⟩", "⟨p = {{24}}⟩, so 24%"]}]};
  N["ratios-proportions-percentages-skill-07"] = {"obj": "solve percent problems with equations, including tax, tip and commission", "idea": "Write part = percent × whole with the percent as a decimal. Tax, tips and commission are each a percent of a base amount.", "voc": [["commission", "Pay that is a percent of a person’s sales."], ["sales tax", "A percent of the price added at purchase."], ["tip", "A percent of a bill given for service."]], "watch": "Finding the tip on the total after tax when the problem says to tip on the bill before tax.", "frame": "The base is ___, so the ___ is ___ × ___.", "cards": [{"h": "Percent equations", "big": "Write part = rate × base.", "steps": ["6% commission on $3,400: ⟨0.06 \\times 3400 = {{204}}⟩", "$48 bill, 20% tip, 6.25% tax: ⟨48 + 9.60 + {{3.00}} = 60.60⟩", "30 is 40% of n: ⟨n = \\frac{30}{0.4} = {{75}}⟩"]}]};
  N["ratios-proportions-percentages-skill-08"] = {"obj": "find percent increase, percent decrease and percent error", "idea": "Percent change is the change divided by the original amount. Percent error is the size of the error divided by the actual value.", "voc": [["percent of change", "⟨\\frac{\\text{amount of change}}{\\text{original amount}}⟩, written as a percent."], ["percent error", "⟨\\frac{|\\text{estimate} - \\text{actual}|}{\\text{actual}}⟩, written as a percent."]], "watch": "Dividing by the new amount instead of the original amount.", "frame": "The change is ___ and the original is ___, so the percent change is ___.", "cards": [{"h": "Change over original", "big": "A price goes from $80 to $92.", "steps": ["Change: ⟨92 - 80 = {{12}}⟩", "⟨\\frac{12}{80} = {{15}}\\%⟩ increase", "Estimate 52, actual 48: ⟨\\frac{4}{48} \\approx {{8.3}}\\%⟩ error"]}]};
  N["ratios-proportions-percentages-skill-09"] = {"obj": "find sale prices and selling prices with markups, discounts and successive changes", "idea": "A discount of p% leaves (100 − p)% of the price; a markup of p% makes (100 + p)%. Successive changes multiply, so 20% off then 10% off is not 30% off.", "voc": [["markup", "The amount added to a cost to set the selling price."], ["discount", "The amount subtracted from the regular price."]], "watch": "Adding successive percents (20% off then 10% off = 30% off).", "frame": "After a ___% discount the price is ___% of the original, so ___.", "cards": [{"h": "Multiply by what is left", "big": "Jacket: $60.", "steps": ["25% off: ⟨0.75 \\times 60 = {{45}}⟩", "20% off, then 10% off: ⟨0.9 \\times 0.8 \\times 60 = {{43.20}}⟩", "Cost $40, markup 35%: ⟨1.35 \\times 40 = {{54}}⟩"]}]};
  N["ratios-proportions-percentages-skill-10"] = {"obj": "recognize proportional relationships in tables, graphs and equations and find the constant of proportionality", "idea": "In a proportional relationship, y ÷ x is the same for every pair, so y = kx. Its graph is a straight line through the origin, and the point (1, k) shows the unit rate.", "voc": [["proportional relationship", "A relationship in which y = kx for a constant k."], ["constant of proportionality", "The constant k = y ÷ x in y = kx; the unit rate."]], "watch": "Calling any straight line proportional; the line must pass through (0, 0).", "frame": "Every ratio y ÷ x is ___, so k = ___ and the equation is ___.", "cards": [{"h": "Find k", "big": "x: 2, 5, 8; y: 7, 17.5, 28.", "steps": ["⟨\\frac{7}{2} = \\frac{17.5}{5} = \\frac{28}{8} = {{3.5}}⟩", "Equation: ⟨y = {{3.5x}}⟩", "The graph passes through (0, 0) and (1, {{3.5}})."]}]};
  N["ratios-proportions-percentages-skill-11"] = {"obj": "rewrite expressions to show how quantities in a situation are related", "idea": "Equivalent expressions can reveal different information: a + 0.05a = 1.05a shows that a 5% increase means multiplying by 1.05.", "voc": [["equivalent expressions", "Expressions that have the same value for every value of the variable."], ["factor", "To rewrite a sum as a product."]], "watch": "Treating a + 0.05a as 0.05a², or not connecting the rewritten form to the context.", "frame": "Rewriting ___ as ___ shows that ___.", "cards": [{"h": "Same value, new meaning", "big": "A price p is increased by 8%.", "steps": ["⟨p + 0.08p = {{1.08}}p⟩", "Perimeter of a square: ⟨s + s + s + s = {{4s}}⟩", "⟨2(L + W)⟩ shows {{the sum of one length and one width}}, doubled."]}]};
  /* ---------- solving-equations-inequalities ---------- */
  N["solving-equations-inequalities-skill-01"] = {"obj": "solve two-step equations of the form px + q = r and p(x + q) = r", "idea": "Undo operations in reverse order: first undo addition or subtraction, then multiplication or division. For p(x + q) = r you can divide by p first.", "voc": [["two-step equation", "An equation that needs two inverse operations to solve."], ["inverse operations", "Operations that undo each other."]], "watch": "Dividing only the variable term by the coefficient (5x + 12 = −8 → x + 12 = −1.6).", "frame": "First I undo ___, then I undo ___.", "cards": [{"h": "Reverse order", "big": "Solve ⟨5x + 12 = -8⟩.", "steps": ["⟨5x = -8 - 12 = {{-20}}⟩", "⟨x = {{-4}}⟩", "⟨3(x - 4) = 21⟩ → ⟨x - 4 = 7⟩, ⟨x = {{11}}⟩"]}]};
  N["solving-equations-inequalities-skill-02"] = {"obj": "solve multi-step equations by distributing and combining like terms", "idea": "Simplify each side first (distribute, combine like terms), then solve the two-step equation that is left.", "voc": [["like terms", "Terms with the same variable part."], ["distributive property", "a(b + c) = ab + ac."]], "watch": "Distributing a negative to the first term only: −2(x − 3) = −2x − 6.", "frame": "I simplify ___ to ___, then solve.", "cards": [{"h": "Simplify, then solve", "big": "Solve ⟨4x - 2(x - 3) = 20⟩.", "steps": ["⟨4x - 2x + {{6}} = 20⟩", "⟨2x = {{14}}⟩", "⟨x = {{7}}⟩"]}]};
  N["solving-equations-inequalities-skill-03"] = {"obj": "solve multi-step equations with fractions and decimals", "idea": "Multiply every term by the least common denominator (or a power of ten) to clear fractions or decimals, then solve.", "voc": [["least common denominator", "The least common multiple of the denominators."], ["clear fractions", "Multiply both sides by a common denominator so no fractions remain."]], "watch": "Multiplying only the fraction terms by the LCD, not every term.", "frame": "I multiply every term by ___ to clear the ___.", "cards": [{"h": "Clear the fractions", "big": "Solve ⟨\\frac{x}{3} + \\frac{1}{2} = \\frac{5}{6}⟩.", "steps": ["Multiply every term by {{6}}: ⟨2x + 3 = 5⟩", "⟨x = {{1}}⟩", "⟨0.4x - 1.2 = 2⟩ → ⟨4x - 12 = 20⟩, ⟨x = {{8}}⟩"]}]};
  N["solving-equations-inequalities-skill-04"] = {"obj": "write and solve an equation to model a word problem", "idea": "Define the variable, write an equation from the words, solve it, and answer the question in a sentence with units.", "voc": [["define a variable", "State what the letter stands for, with units."], ["model", "An equation or expression that represents a situation."]], "watch": "Answering with the value of the variable when the question asks for something else (the other number, or a total).", "frame": "Let ___ be ___. Then the equation is ___.", "cards": [{"h": "Model, solve, answer", "big": "A plumber charges $45 plus $60 an hour. The bill is $285.", "steps": ["Let h = hours: ⟨45 + 60h = 285⟩", "⟨60h = 240⟩, ⟨h = {{4}}⟩", "The plumber worked {{4 hours}}."]}]};
  N["solving-equations-inequalities-skill-05"] = {"obj": "solve equations with variables on both sides and recognize one, none or infinitely many solutions", "idea": "Collect the variable terms on one side. If the variables cancel and a true statement is left, every number is a solution; if a false statement is left, there is no solution.", "voc": [["identity", "An equation true for every value of the variable."], ["no solution", "An equation that is false for every value of the variable."]], "watch": "Writing x = 0 when the variables cancel, instead of deciding between no solution and infinitely many.", "frame": "After collecting terms I get ___, so the equation has ___.", "cards": [{"h": "One, none or infinitely many", "big": "Collect the variables on one side.", "steps": ["⟨5x - 4 = 2x + 11⟩ → ⟨x = {{5}}⟩", "⟨3(x + 2) = 3x + 5⟩ → ⟨6 = 5⟩: {{no solution}}", "⟨2(x - 1) = 2x - 2⟩: {{infinitely many}}"]}]};
  N["solving-equations-inequalities-skill-06"] = {"obj": "solve two-step inequalities, graph the solutions and interpret them in context", "idea": "Solve like a two-step equation, reversing the symbol if you multiply or divide by a negative. In context, check whether the answer must be a whole number.", "voc": [["solution set", "All the values that make an inequality true."], ["reverse the inequality", "Change the direction of the symbol after multiplying or dividing by a negative."]], "watch": "Forgetting to reverse the symbol when dividing by a negative coefficient.", "frame": "I divided by ___, so the symbol ___. In context the answer means ___.", "cards": [{"h": "Two steps and context", "big": "You have $50 and spend $8 per ticket after a $10 fee.", "steps": ["⟨10 + 8t \\le 50⟩ → ⟨t \\le {{5}}⟩", "At most {{5}} tickets.", "⟨-2x + 7 > 15⟩ → ⟨x {{<}} -4⟩"]}]};
  N["solving-equations-inequalities-skill-07"] = {"obj": "solve a formula for one of its variables", "idea": "Treat the other letters like numbers and use inverse operations to isolate the variable you want.", "voc": [["literal equation", "An equation with two or more variables, such as a formula."], ["isolate", "Get one variable alone on one side."]], "watch": "Dividing only one term on a side by the coefficient.", "frame": "To get ___ alone, I ___ both sides by ___.", "cards": [{"h": "Solve for a letter", "big": "Solve ⟨P = 2L + 2W⟩ for W.", "steps": ["⟨P - 2L = {{2W}}⟩", "⟨W = {{\\frac{P - 2L}{2}}}⟩", "⟨d = rt⟩ for t: ⟨t = {{\\frac{d}{r}}}⟩"]}]};
  N["solving-equations-inequalities-skill-08"] = {"obj": "find simple and compound interest", "idea": "Simple interest grows by the same amount each year: I = Prt. Compound interest earns interest on interest: ⟨A = P(1 + r)^t⟩.", "voc": [["principal", "The amount of money deposited or borrowed."], ["simple interest", "Interest paid only on the principal."], ["compound interest", "Interest paid on the principal and on interest already earned."]], "watch": "Using the percent as a whole number (r = 4 instead of 0.04).", "frame": "The principal is ___, the rate is ___ and the time is ___, so ___.", "cards": [{"h": "Simple vs compound", "big": "$2,000 at 4% for 3 years.", "steps": ["Simple: ⟨2000(0.04)(3) = {{240}}⟩", "Compound: ⟨2000(1.04)^3 \\approx {{2249.73}}⟩", "Compound earns {{$9.73}} more."]}]};
  /* ---------- linear-functions-graphing ---------- */
  N["linear-functions-graphing-skill-01"] = {"obj": "decide whether a relation is a function and read qualitative graphs", "idea": "A function gives exactly one output for each input. On a graph, no vertical line crosses it twice. A graph’s shape tells a story: rising, falling, flat, steep.", "voc": [["relation", "A set of ordered pairs."], ["function", "A relation that gives exactly one output for each input."], ["vertical line test", "A graph is a function if no vertical line crosses it more than once."]], "watch": "Rejecting a function because two inputs share an output; that is allowed.", "frame": "This is (not) a function because the input ___ has ___ output(s).", "cards": [{"h": "One output per input", "big": "Check the inputs.", "steps": ["{(1, 4), (2, 4), (3, 5)}: {{function}}", "{(2, 1), (2, 6), (4, 0)}: {{not a function}}", "A flat part of a distance–time graph means {{stopped}}."]}]};
  N["linear-functions-graphing-skill-02"] = {"obj": "find solutions of equations in two variables and graph them", "idea": "A solution of an equation in x and y is an ordered pair that makes it true. Make a table of solutions and plot them; for a linear equation they lie on a line.", "voc": [["solution of a two-variable equation", "An ordered pair (x, y) that makes the equation true."], ["linear equation", "An equation whose graph is a straight line."]], "watch": "Substituting the x-value for y.", "frame": "When x = ___, y = ___, so ___ is a solution.", "cards": [{"h": "Table, then graph", "big": "Graph ⟨y = 2x - 3⟩.", "steps": ["x = 0 → y = {{−3}}", "x = 2 → y = {{1}}", "Is (4, 6) a solution? 2(4) − 3 = 5, so {{no}}."]}]};
  N["linear-functions-graphing-skill-03"] = {"obj": "find slope and y-intercept from a graph, table or two points and graph y = mx + b", "idea": "Slope is rise over run, the rate of change. In y = mx + b, m is the slope and b is the y-intercept. Proportional relationships are the case b = 0.", "voc": [["slope", "⟨\\frac{\\text{change in }y}{\\text{change in }x}⟩, the rate of change."], ["y-intercept", "The y-value where a line crosses the y-axis."]], "watch": "Computing run over rise, or subtracting the coordinates in different orders.", "frame": "From ___ to ___ the rise is ___ and the run is ___, so the slope is ___.", "cards": [{"h": "Rise over run", "big": "Points (1, 2) and (4, 11).", "steps": ["⟨m = \\frac{11 - 2}{4 - 1} = {{3}}⟩", "⟨2 = 3(1) + b⟩, so ⟨b = {{-1}}⟩", "⟨y = {{3x - 1}}⟩"]}]};
  N["linear-functions-graphing-skill-04"] = {"obj": "write a rule for a linear function from a table, graph or description and compare two functions", "idea": "Find the rate of change (the slope) and the starting value (the y-intercept), then write y = mx + b. Compare functions by their rates and starting values.", "voc": [["rate of change", "How much y changes for each increase of 1 in x."], ["initial value", "The value of y when x = 0."]], "watch": "Using the first y-value in a table as b when the table does not start at x = 0.", "frame": "The rate of change is ___ and the initial value is ___, so ___.", "cards": [{"h": "Rate and start", "big": "Plan A: ⟨y = 12x + 30⟩. Plan B: x 0, 1, 2; y 15, 30, 45.", "steps": ["Plan B rate: {{15}} per month, start {{0}}", "Plan B: ⟨y = {{15x}}⟩", "B costs more per month; they cost the same at x = {{10}}."]}]};
  N["linear-functions-graphing-skill-05"] = {"obj": "make scatter plots, describe the association and use a trend line to predict", "idea": "A scatter plot shows paired data. Describe the association (positive, negative, none; linear or not) and draw a trend line close to most points to make predictions.", "voc": [["scatter plot", "A graph of paired data as points."], ["positive association", "As one variable increases, the other tends to increase."], ["trend line", "A line that models the data in a scatter plot."]], "watch": "Treating association as proof that one variable causes the other.", "frame": "As ___ increases, ___ tends to ___, so the association is ___.", "cards": [{"h": "Use a trend line", "big": "Trend line: ⟨y = 2.5x + 60⟩, x = hours studied, y = score.", "steps": ["The association is {{positive}}.", "For 8 hours: ⟨2.5(8) + 60 = {{80}}⟩", "Slope 2.5 means {{2.5 points}} per extra hour."]}]};
  N["linear-functions-graphing-skill-06"] = {"obj": "solve systems of linear equations by graphing", "idea": "The solution of a system is the point that lies on both lines. Parallel lines give no solution; the same line gives infinitely many.", "voc": [["system of linear equations", "Two or more linear equations with the same variables."], ["solution of a system", "An ordered pair that makes every equation true."]], "watch": "Reading the intersection only approximately and not checking it in both equations.", "frame": "The lines cross at ___, which checks in both equations.", "cards": [{"h": "Where the lines meet", "big": "⟨y = x + 1⟩ and ⟨y = -2x + 7⟩.", "steps": ["Intersection: ({{2}}, {{3}})", "Check: 3 = 2 + 1 and 3 = −4 + 7 ✓", "Same slope, different intercepts: {{no solution}}"]}]};
  N["linear-functions-graphing-skill-07"] = {"obj": "solve systems by substitution and model real problems with systems", "idea": "Solve one equation for a variable, substitute that expression into the other equation, solve, and substitute back.", "voc": [["substitution", "Replacing a variable with an equal expression."], ["system of equations", "Equations that must be true at the same time."]], "watch": "Stopping after finding one variable.", "frame": "I substitute ___ for ___ in the other equation.", "cards": [{"h": "Substitute", "big": "Adult tickets $8, child $5; 20 tickets, $133.", "steps": ["⟨a + c = 20⟩, so ⟨c = 20 - a⟩", "⟨8a + 5(20 - a) = 133⟩ → ⟨a = {{11}}⟩", "⟨c = {{9}}⟩ child tickets"]}]};
  N["linear-functions-graphing-skill-08"] = {"obj": "graph linear inequalities in two variables", "idea": "Graph the boundary line (dashed for < or >, solid for ≤ or ≥), then shade the side whose points make the inequality true; test a point such as (0, 0).", "voc": [["boundary line", "The line that separates the solutions from the non-solutions."], ["half-plane", "The region on one side of a line."]], "watch": "Shading by the direction of the symbol alone when the inequality is not solved for y.", "frame": "The line is ___ because ___. The test point ___ is (not) a solution, so I shade ___.", "cards": [{"h": "Line, then shade", "big": "Graph ⟨y < 2x + 1⟩.", "steps": ["The boundary is {{dashed}}.", "Test (0, 0): 0 < 1, {{true}}", "Shade the side containing {{(0, 0)}}, below the line."]}]};
  /* ---------- spatial-thinking ---------- */
  N["spatial-thinking-skill-01"] = {"obj": "name points, lines, planes, segments and rays and describe how they intersect", "idea": "Points, lines and planes are the building blocks of geometry. Name a figure with its points; two lines meet in a point, and two planes meet in a line.", "voc": [["segment", "Part of a line with two endpoints."], ["ray", "Part of a line with one endpoint that extends forever in one direction."], ["skew lines", "Lines that are not in the same plane and do not intersect."]], "watch": "Naming a ray with its endpoint second (ray BA for a ray starting at A).", "frame": "___ and ___ intersect at ___.", "cards": [{"h": "Name it", "big": "Points A, B, C on line ℓ, in that order.", "steps": ["Ray from A through B: ray {{AB}}", "Segment with endpoints B and C: {{BC}}", "Two different planes meet in a {{line}}."]}]};
  N["spatial-thinking-skill-02"] = {"obj": "use angle relationships to write and solve equations for unknown angles", "idea": "Supplementary angles sum to 180°, complementary to 90°; vertical angles are equal. Parallel lines cut by a transversal make equal corresponding and alternate interior angles.", "voc": [["supplementary angles", "Two angles whose measures add to 180°."], ["complementary angles", "Two angles whose measures add to 90°."], ["vertical angles", "Opposite angles formed by two intersecting lines; they are equal."]], "watch": "Setting vertical angles to add to 180° instead of being equal.", "frame": "The angles are ___, so I write the equation ___.", "cards": [{"h": "Write an equation", "big": "Angles (2x + 10)° and (3x − 5)° are supplementary.", "steps": ["⟨(2x + 10) + (3x - 5) = {{180}}⟩", "⟨5x + 5 = 180⟩, ⟨x = {{35}}⟩", "The angles are {{80°}} and {{100°}}."]}]};
  N["spatial-thinking-skill-03"] = {"obj": "classify polygons and use the angle sum of a polygon", "idea": "Polygons are named by their number of sides. A triangle’s angles sum to 180°, and an n-gon’s angles sum to (n − 2) · 180°.", "voc": [["polygon", "A closed plane figure made of segments that meet only at their endpoints."], ["regular polygon", "A polygon with all sides and all angles equal."], ["quadrilateral", "A polygon with four sides."]], "watch": "Using n · 180° for the angle sum.", "frame": "A ___ has ___ sides, so its angles sum to ___.", "cards": [{"h": "Angle sums", "big": "Use ⟨(n - 2) \\cdot 180°⟩.", "steps": ["Hexagon: ⟨4 \\cdot 180° = {{720°}}⟩", "Each angle of a regular hexagon: {{120°}}", "Triangle with 47° and 68°: third angle {{65°}}"]}]};
  N["spatial-thinking-skill-04"] = {"obj": "draw a diagram to plan and solve a problem", "idea": "A labeled sketch turns words into a picture you can count, measure or reason about. Mark every given fact on it before you compute.", "voc": [["diagram", "A drawing that shows the parts of a problem and how they relate."], ["label", "A name or measurement written on a diagram."]], "watch": "Drawing a diagram but not putting the numbers from the problem on it.", "frame": "My diagram shows ___, so I can see that ___.", "cards": [{"h": "Sketch it", "big": "A 20-ft fence has a post every 4 ft, including both ends.", "steps": ["Mark posts at 0, 4, 8, 12, 16, {{20}}.", "Count: {{6}} posts", "Not 20 ÷ 4 = 5: the diagram shows the {{extra end post}}."]}]};
  N["spatial-thinking-skill-05"] = {"obj": "identify congruent figures and their corresponding parts", "idea": "Congruent figures have the same size and shape; one can be moved onto the other by rigid motions. Corresponding sides and angles are equal, and the order of letters shows which parts match.", "voc": [["congruent", "Having the same size and shape."], ["corresponding parts", "Matching sides and angles of congruent figures."], ["rigid motion", "A translation, reflection or rotation; it keeps lengths and angles."]], "watch": "Matching parts by position on the page instead of by the order of the letters.", "frame": "Because △___ ≅ △___, side ___ corresponds to side ___.", "cards": [{"h": "Read the order", "big": "△ABC ≅ △DEF.", "steps": ["∠B corresponds to ∠{{E}}.", "If AC = 9 cm, then {{DF}} = 9 cm.", "If ∠C = 40°, then ∠{{F}} = 40°."]}]};
  N["spatial-thinking-skill-06"] = {"obj": "find the circumference of a circle and relate it to the diameter", "idea": "Every circle’s circumference is π times its diameter, C = πd = 2πr, so C ÷ d = π ≈ 3.14.", "voc": [["circumference", "The distance around a circle."], ["diameter", "A segment through the center with endpoints on the circle; twice the radius."], ["π (pi)", "The ratio of any circle’s circumference to its diameter, about 3.14."]], "watch": "Using the radius in C = πd, which gives half the circumference.", "frame": "The diameter is ___, so the circumference is π × ___ ≈ ___.", "cards": [{"h": "C = πd", "big": "Radius 7 cm.", "steps": ["⟨d = {{14}}⟩ cm", "⟨C = 14\\pi \\approx {{43.96}}⟩ cm (with 3.14)", "If C = 31.4 in., then ⟨d = {{10}}⟩ in."]}]};
  N["spatial-thinking-skill-07"] = {"obj": "construct figures and decide when given conditions make a unique triangle, many triangles or none", "idea": "Three lengths make a triangle only if each pair sums to more than the third. Three sides, or two sides and the angle between them, fix a unique triangle; three angles fix only the shape.", "voc": [["triangle inequality", "The sum of any two side lengths of a triangle is greater than the third."], ["construction", "A drawing made with a compass and straightedge."], ["perpendicular bisector", "A line perpendicular to a segment through its midpoint."]], "watch": "Checking only one pair of sides (or only the two shortest) and missing a case where the sum equals the third side.", "frame": "Since ___ + ___ is (not) greater than ___, the lengths (do not) make a triangle.", "cards": [{"h": "One, many or none?", "big": "Test the conditions.", "steps": ["3, 4, 8: 3 + 4 = 7 < 8, {{no triangle}}", "5, 7, 9: {{one}} triangle", "Angles 50°, 60°, 70°: {{many}} triangles (same shape, any size)"]}]};
  N["spatial-thinking-skill-08"] = {"obj": "translate figures on the coordinate plane and describe translations with rules", "idea": "A translation slides every point the same distance in the same direction: (x, y) → (x + a, y + b). The image is congruent to the original.", "voc": [["translation", "A slide that moves every point the same distance and direction."], ["image", "The figure after a transformation, labeled with primes such as A′."]], "watch": "Adding the horizontal shift to y or the vertical shift to x.", "frame": "Each point moves ___ units ___ and ___ units ___, so the rule is ___.", "cards": [{"h": "Slide every point", "big": "Rule: (x, y) → (x − 4, y + 3).", "steps": ["A(2, 1) → A′({{−2}}, {{4}})", "B(−1, −5) → B′({{−5}}, {{−2}})", "The image is {{congruent}} to the original."]}]};
  N["spatial-thinking-skill-09"] = {"obj": "identify line and rotational symmetry and reflect figures", "idea": "A figure has line symmetry if a reflection maps it onto itself, and rotational symmetry if a rotation of less than 360° does. A reflection over the y-axis maps (x, y) to (−x, y).", "voc": [["line of symmetry", "A line that divides a figure into two mirror-image halves."], ["rotational symmetry", "A figure has it if a turn of less than 360° maps it onto itself."], ["reflection", "A flip over a line."]], "watch": "Counting the diagonals of a rectangle as lines of symmetry.", "frame": "The figure has ___ lines of symmetry and rotational symmetry of order ___.", "cards": [{"h": "Symmetry", "big": "Look for flips and turns that map the figure onto itself.", "steps": ["A square has {{4}} lines of symmetry.", "A regular hexagon has rotational symmetry every {{60°}}.", "Reflect (3, −2) over the y-axis: ({{−3}}, {{−2}})"]}]};
  N["spatial-thinking-skill-10"] = {"obj": "rotate figures 90°, 180° and 270° about the origin", "idea": "A rotation turns every point about a center. Counterclockwise about the origin: 90° maps (x, y) to (−y, x) and 180° maps it to (−x, −y).", "voc": [["rotation", "A turn of a figure about a fixed point."], ["center of rotation", "The fixed point a figure turns around."], ["angle of rotation", "How far the figure turns."]], "watch": "Swapping the coordinates without changing a sign, or turning clockwise when the problem says counterclockwise.", "frame": "A ___° rotation maps ___ to ___.", "cards": [{"h": "Rotation rules", "big": "Counterclockwise about the origin.", "steps": ["90°: (4, 1) → ({{−1}}, {{4}})", "180°: (4, 1) → ({{−4}}, {{−1}})", "270°: (4, 1) → ({{1}}, {{−4}})"]}]};
  /* ---------- area-volume ---------- */
  N["area-volume-skill-01"] = {"obj": "find the area of parallelograms using base and height", "idea": "Cutting a triangle off one side of a parallelogram and moving it makes a rectangle, so A = bh, where h is perpendicular to the base.", "voc": [["base", "Any side of a parallelogram, used with the height."], ["height", "The perpendicular distance between the base and the opposite side."]], "watch": "Using the slanted side as the height.", "frame": "The base is ___ and the perpendicular height is ___, so the area is ___.", "cards": [{"h": "A = bh", "big": "Base 12 cm, slanted side 7 cm, height 5 cm.", "steps": ["⟨A = 12 \\times {{5}}⟩", "⟨A = {{60}}\\text{ cm}^2⟩", "The 7-cm side is {{not}} the height."]}], "review": true};
  N["area-volume-skill-02"] = {"obj": "find the area of triangles and trapezoids", "idea": "A triangle is half of a parallelogram: ⟨A = \\frac{1}{2}bh⟩. A trapezoid is half of a parallelogram with base b₁ + b₂: ⟨A = \\frac{1}{2}(b_1 + b_2)h⟩.", "voc": [["trapezoid", "A quadrilateral with exactly one pair of parallel sides."], ["bases of a trapezoid", "The two parallel sides."]], "watch": "Forgetting the ⟨\\frac{1}{2}⟩, or adding a slanted side as one of the bases.", "frame": "I use ___ for the bases and ___ for the height.", "cards": [{"h": "Half of a parallelogram", "big": "Use the perpendicular height.", "steps": ["Triangle, b = 10, h = 6: ⟨A = {{30}}⟩", "Trapezoid, bases 8 and 14, h = 5: ⟨\\frac{1}{2}(22)(5) = {{55}}⟩", "The units are {{square}} units."]}], "review": true};
  N["area-volume-skill-03"] = {"obj": "find the area of circles and of figures made from circles", "idea": "Cut a circle into thin sectors and rearrange them into a near-parallelogram with base πr and height r, so A = πr².", "voc": [["area of a circle", "A = πr², where r is the radius."], ["semicircle", "Half of a circle."]], "watch": "Squaring the diameter, or computing 2πr (the circumference) for area.", "frame": "The radius is ___, so the area is π × ___² ≈ ___.", "cards": [{"h": "A = πr²", "big": "Diameter 10 m.", "steps": ["⟨r = {{5}}⟩ m", "⟨A = 25\\pi \\approx {{78.5}}\\text{ m}^2⟩ (with 3.14)", "Semicircle with r = 4: ⟨8\\pi \\approx {{25.12}}⟩"]}]};
  N["area-volume-skill-04"] = {"obj": "name solids, count faces, edges and vertices, and describe cross-sections", "idea": "Prisms have two congruent bases; pyramids have one base and triangular faces. Slicing a solid with a plane makes a cross-section, whose shape depends on how the plane cuts.", "voc": [["prism", "A solid with two congruent, parallel bases joined by rectangles."], ["pyramid", "A solid with one polygon base and triangular faces meeting at a vertex."], ["cross-section", "The shape formed where a plane slices a solid."]], "watch": "Thinking every slice of a prism is congruent to the base; a slice perpendicular to the base is a rectangle.", "frame": "A slice ___ to the base of a ___ is a ___.", "cards": [{"h": "Faces and slices", "big": "Rectangular prism and square pyramid.", "steps": ["Rectangular prism: 6 faces, {{12}} edges, 8 vertices", "Square pyramid sliced parallel to the base: a {{square}}", "Cylinder sliced perpendicular to the base: a {{rectangle}}"]}]};
  N["area-volume-skill-05"] = {"obj": "find the surface area of prisms and cylinders", "idea": "Surface area is the total area of all the faces, like the area of the net. For a cylinder, the side unrolls into a rectangle 2πr long and h high.", "voc": [["surface area", "The total area of the surfaces of a solid."], ["net", "A flat pattern that folds into a solid."], ["lateral area", "The area of the sides, not including the bases."]], "watch": "Counting only three faces of a rectangular prism instead of all six.", "frame": "The faces are ___, so the surface area is ___.", "cards": [{"h": "Add the faces", "big": "Box 5 × 3 × 2 in.; cylinder r = 3, h = 10.", "steps": ["Box: ⟨2(15 + 10 + 6) = {{62}}\\text{ in.}^2⟩", "Cylinder bases: ⟨2\\pi(9) = 18\\pi⟩", "Side: ⟨2\\pi(3)(10) = 60\\pi⟩; total ⟨{{78\\pi}} \\approx 245.0⟩"]}]};
  N["area-volume-skill-06"] = {"obj": "find the surface area of pyramids, cones and spheres", "idea": "A pyramid’s surface is its base plus triangles that use the slant height; a cone’s is πr² + πrℓ; a sphere’s is 4πr².", "voc": [["slant height", "The height of a lateral face of a pyramid or cone, measured along the surface."], ["sphere", "All points in space the same distance from a center."]], "watch": "Using the height instead of the slant height for the lateral faces.", "frame": "The slant height is ___, so the lateral area is ___.", "cards": [{"h": "Base plus lateral", "big": "Square pyramid: base 6, slant height 5.", "steps": ["Base: {{36}}", "Four triangles: ⟨4 \\cdot \\frac{1}{2}(6)(5) = {{60}}⟩; total {{96}}", "Sphere r = 3: ⟨4\\pi(9) = {{36\\pi}}⟩"]}]};
  N["area-volume-skill-07"] = {"obj": "find the volume of prisms and cylinders and solve volume problems", "idea": "Volume is the area of the base times the height, V = Bh, because the solid is layers of the base stacked h high.", "voc": [["volume", "The number of cubic units that fill a solid."], ["B (base area)", "The area of the base of a prism or cylinder."]], "watch": "Using the area formula of the wrong face as B, or writing square units for volume.", "frame": "The base area is ___ and the height is ___, so the volume is ___.", "cards": [{"h": "V = Bh", "big": "Stack the base.", "steps": ["Prism 4 × 5 base, h = 6: ⟨V = {{120}}⟩ cubic units", "Cylinder r = 2, h = 9: ⟨V = \\pi(4)(9) = {{36\\pi}}⟩", "A prism with B = 30 and V = 210 has ⟨h = {{7}}⟩."]}]};
  N["area-volume-skill-08"] = {"obj": "find the volume of pyramids, cones and spheres", "idea": "A pyramid or cone holds one third of the prism or cylinder with the same base and height: ⟨V = \\frac{1}{3}Bh⟩. A sphere: ⟨V = \\frac{4}{3}\\pi r^3⟩.", "voc": [["cone", "A solid with a circular base and one vertex."], ["volume of a sphere", "⟨V = \\frac{4}{3}\\pi r^3⟩."]], "watch": "Forgetting the ⟨\\frac{1}{3}⟩, or using the slant height as the height.", "frame": "The cone is ___ of the cylinder with the same base and height, so ___.", "cards": [{"h": "One third", "big": "Same base and height as a cylinder.", "steps": ["Cone r = 3, h = 8: ⟨\\frac{1}{3}\\pi(9)(8) = {{24\\pi}}⟩", "Pyramid B = 36, h = 10: ⟨V = {{120}}⟩", "Sphere r = 3: ⟨\\frac{4}{3}\\pi(27) = {{36\\pi}}⟩"]}]};
  /* ---------- right-triangles-algebra ---------- */
  N["right-triangles-algebra-skill-01"] = {"obj": "find square roots, estimate irrational square roots and solve ⟨x^2 = p⟩", "idea": "A square root undoes squaring. ⟨x^2 = p⟩ has two solutions, ⟨\\pm\\sqrt{p}⟩. The square root of a non-perfect square is irrational and lies between two whole numbers.", "voc": [["square root", "A number that, multiplied by itself, gives the original number."], ["principal square root", "The nonnegative square root, written ⟨\\sqrt{p}⟩."]], "watch": "Giving only the positive solution of ⟨x^2 = 36⟩.", "frame": "The square root of ___ is ___ because ___ squared is ___.", "cards": [{"h": "Roots and estimates", "big": "Undo the square.", "steps": ["⟨\\sqrt{81} = {{9}}⟩", "⟨x^2 = 36⟩ → ⟨x = {{\\pm 6}}⟩", "⟨\\sqrt{30}⟩ is between 5 and {{6}}, closer to {{5}}."]}]};
  N["right-triangles-algebra-skill-02"] = {"obj": "use the Pythagorean theorem and its converse to find lengths and test for right triangles", "idea": "In a right triangle, ⟨a^2 + b^2 = c^2⟩, where c is the hypotenuse (opposite the right angle). If the side lengths satisfy it, the triangle is a right triangle.", "voc": [["hypotenuse", "The side opposite the right angle; the longest side."], ["legs", "The two sides that form the right angle."], ["converse", "If ⟨a^2 + b^2 = c^2⟩, the triangle is a right triangle."]], "watch": "Adding the hypotenuse squared to a leg squared when finding a missing leg.", "frame": "The hypotenuse is ___, so ___² + ___² = ___².", "cards": [{"h": "a² + b² = c²", "big": "Find the missing side.", "steps": ["Legs 6 and 8: ⟨c = \\sqrt{100} = {{10}}⟩", "Leg 5, hypotenuse 13: ⟨b = \\sqrt{169 - 25} = {{12}}⟩", "7, 8, 11: ⟨49 + 64 = 113 \\ne 121⟩, {{not}} a right triangle"]}]};
  N["right-triangles-algebra-skill-03"] = {"obj": "find the distance between two points and the midpoint of a segment", "idea": "The distance between two points is the hypotenuse of a right triangle with legs |x₂ − x₁| and |y₂ − y₁|. The midpoint averages the coordinates.", "voc": [["distance formula", "⟨d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}⟩."], ["midpoint", "The point halfway between two endpoints: the average of the x’s and of the y’s."]], "watch": "Subtracting x from y, or forgetting to take the square root.", "frame": "The legs are ___ and ___, so the distance is ___.", "cards": [{"h": "Draw the right triangle", "big": "From (1, 2) to (7, 10).", "steps": ["Legs: 6 and {{8}}", "⟨d = \\sqrt{36 + 64} = {{10}}⟩", "Midpoint: ({{4}}, {{6}})"]}]};
  N["right-triangles-algebra-skill-04"] = {"obj": "write and solve a proportion for a real situation", "idea": "Set up two equal ratios with matching units in matching positions, then solve. Label the units to check the setup.", "voc": [["proportion", "An equation stating that two ratios are equal."], ["unit rate", "A rate for one unit of the second quantity."]], "watch": "Mixing the order of the quantities in the two ratios.", "frame": "Both ratios compare ___ to ___, so I write ___.", "cards": [{"h": "Match the units", "big": "A 6-ft person casts a 4-ft shadow; a tree casts a 30-ft shadow.", "steps": ["⟨\\frac{6}{4} = \\frac{h}{30}⟩", "⟨4h = {{180}}⟩", "⟨h = {{45}}⟩ ft"]}]};
  N["right-triangles-algebra-skill-05"] = {"obj": "use the side ratios of 45°-45°-90° and 30°-60°-90° triangles", "idea": "In a 45°-45°-90° triangle the hypotenuse is ⟨\\sqrt{2}⟩ times a leg. In a 30°-60°-90° triangle the hypotenuse is twice the short leg and the long leg is ⟨\\sqrt{3}⟩ times the short leg.", "voc": [["45°-45°-90° triangle", "An isosceles right triangle; sides in the ratio 1 : 1 : ⟨\\sqrt{2}⟩."], ["30°-60°-90° triangle", "Half of an equilateral triangle; sides in the ratio 1 : ⟨\\sqrt{3}⟩ : 2."]], "watch": "Putting ⟨\\sqrt{3}⟩ on the hypotenuse instead of the long leg.", "frame": "The short leg is ___, so the hypotenuse is ___ and the long leg is ___.", "cards": [{"h": "Special ratios", "big": "Use the patterns.", "steps": ["45°-45°-90°, leg 5: hypotenuse ⟨{{5\\sqrt{2}}}⟩", "30°-60°-90°, short leg 4: hypotenuse {{8}}", "Long leg: ⟨{{4\\sqrt{3}}}⟩"]}]};
  N["right-triangles-algebra-skill-06"] = {"obj": "find sine, cosine and tangent ratios and use them to find side lengths", "idea": "For an acute angle of a right triangle: sin = opposite ÷ hypotenuse, cos = adjacent ÷ hypotenuse, tan = opposite ÷ adjacent (SOH-CAH-TOA).", "voc": [["sine", "opposite ÷ hypotenuse."], ["cosine", "adjacent ÷ hypotenuse."], ["tangent", "opposite ÷ adjacent."]], "watch": "Labeling opposite and adjacent from the wrong angle.", "frame": "For angle ___, the opposite side is ___ and the adjacent side is ___.", "cards": [{"h": "SOH-CAH-TOA", "big": "Right triangle with legs 3 and 4, hypotenuse 5; angle A opposite the side 3.", "steps": ["⟨\\sin A = {{\\frac{3}{5}}}⟩", "⟨\\tan A = {{\\frac{3}{4}}}⟩", "⟨x = 10\\sin 30° = {{5}}⟩"]}]};
  N["right-triangles-algebra-skill-07"] = {"obj": "solve problems with angles of elevation and depression", "idea": "An angle of elevation is measured up from the horizontal; an angle of depression is measured down from the horizontal. Draw the right triangle, then use a trig ratio.", "voc": [["angle of elevation", "The angle from the horizontal up to the line of sight."], ["angle of depression", "The angle from the horizontal down to the line of sight."]], "watch": "Measuring the angle of depression from the vertical.", "frame": "The angle is ___ and I know the ___ side, so I use ___.", "cards": [{"h": "Draw the triangle", "big": "From 40 m away, the angle of elevation to a tower top is 35°.", "steps": ["⟨\\tan 35° = \\frac{h}{40}⟩", "⟨h = 40\\tan 35° \\approx {{28.0}}⟩ m", "Angles of elevation and depression between two points are {{equal}}."]}]};
  /* ---------- data-analysis-probability ---------- */
  N["data-analysis-probability-skill-01"] = {"obj": "organize data in frequency tables, line plots, histograms and two-way tables", "idea": "A frequency table counts how often each value or interval occurs; a histogram graphs those counts with touching bars. A two-way table shows counts for two categorical variables, and its row or column relative frequencies show association.", "voc": [["frequency", "The number of times a value or interval occurs."], ["histogram", "A bar graph of frequencies for equal intervals, with no gaps between bars."], ["two-way table", "A table of counts for two categorical variables."]], "watch": "Using unequal intervals in a histogram, or comparing counts in a two-way table instead of relative frequencies.", "frame": "Of the ___, ___% are ___, compared with ___% of the ___.", "cards": [{"h": "Two-way table", "big": "50 students: 30 play a sport (18 also play music); 20 do not (6 play music).", "steps": ["Of the athletes, ⟨\\frac{18}{30} = {{60}}\\%⟩ play music.", "Of the non-athletes, ⟨\\frac{6}{20} = {{30}}\\%⟩ play music.", "The rates differ, so there is {{an association}}."]}]};
  N["data-analysis-probability-skill-02"] = {"obj": "make and read box-and-whisker plots", "idea": "A box plot shows the five-number summary: minimum, Q1, median, Q3 and maximum. The box holds the middle half of the data, and its length is the interquartile range.", "voc": [["quartile", "A value that divides ordered data into quarters."], ["interquartile range (IQR)", "Q3 − Q1, the spread of the middle half of the data."], ["five-number summary", "Minimum, Q1, median, Q3 and maximum."]], "watch": "Reading the longer section of the plot as having more data; each section holds about a quarter of the values.", "frame": "The median is ___ and the IQR is ___, so the middle half of the data is between ___ and ___.", "cards": [{"h": "Five numbers", "big": "3, 5, 7, 8, 10, 12, 15, 18.", "steps": ["Median: ⟨\\frac{8 + 10}{2} = {{9}}⟩", "Q1 = {{6}}, Q3 = {{13.5}}", "IQR: {{7.5}}"]}], "review": true};
  N["data-analysis-probability-skill-03"] = {"obj": "make and read stem-and-leaf plots, including back-to-back plots", "idea": "A stem-and-leaf plot keeps every value: the stem is all but the last digit and the leaf is the last digit. Back-to-back plots compare two data sets on one stem.", "voc": [["stem", "The digits of a value except the last one."], ["leaf", "The last digit of a value."], ["key", "A note showing how to read the plot, such as 4 | 7 = 47."]], "watch": "Leaving out a stem with no leaves, which hides a gap in the data.", "frame": "The key shows ___ means ___, so the values are ___.", "cards": [{"h": "Read the plot", "big": "Stems 2, 3, 4; leaves 2 | 5 8, 3 | 1 1 6, 4 | 0.", "steps": ["Values: 25, 28, 31, 31, 36, {{40}}", "Mode: {{31}}", "Median: {{31}}"]}], "review": true};
  N["data-analysis-probability-skill-04"] = {"obj": "count outcomes with lists, tree diagrams and the counting principle, and find probabilities", "idea": "If one choice has m outcomes and a second has n, together they have m × n outcomes. With equally likely outcomes, probability is favorable ÷ total.", "voc": [["sample space", "The set of all possible outcomes."], ["counting principle", "If one event has m outcomes and another has n, together there are m · n outcomes."], ["tree diagram", "A diagram that branches to show every outcome."]], "watch": "Adding the numbers of choices instead of multiplying them.", "frame": "There are ___ × ___ = ___ outcomes, and ___ of them are favorable.", "cards": [{"h": "Multiply the choices", "big": "Roll a number cube and flip a coin.", "steps": ["Outcomes: ⟨6 \\times 2 = {{12}}⟩", "P(even and heads) = ⟨\\frac{3}{12} = {{\\frac{1}{4}}}⟩", "3 shirts and 4 pants make {{12}} outfits."]}]};
  N["data-analysis-probability-skill-05"] = {"obj": "find probabilities of independent and dependent compound events", "idea": "For independent events, P(A and B) = P(A) · P(B). If the first event changes the second (drawing without replacement), use the new probability for the second.", "voc": [["independent events", "Events where one does not affect the probability of the other."], ["dependent events", "Events where the outcome of one changes the probability of the other."], ["compound event", "An event made of two or more simple events."]], "watch": "Using the original totals for the second draw when there is no replacement.", "frame": "After the first draw there are ___ left, so P(second) = ___.", "cards": [{"h": "With and without replacement", "big": "A bag has 4 red and 6 blue marbles. Draw two.", "steps": ["With replacement: ⟨\\frac{4}{10} \\cdot \\frac{4}{10} = {{\\frac{4}{25}}}⟩", "Without: ⟨\\frac{4}{10} \\cdot {{\\frac{3}{9}}}⟩", "⟨= {{\\frac{2}{15}}}⟩"]}]};
  N["data-analysis-probability-skill-06"] = {"obj": "count permutations and combinations", "idea": "In a permutation order matters; in a combination it does not. A combination count is the permutation count divided by the number of orders of the chosen items.", "voc": [["permutation", "An arrangement in which order matters."], ["combination", "A selection in which order does not matter."], ["factorial", "n! = n(n − 1)(n − 2)⋯1."]], "watch": "Using a permutation when choosing a committee, where order does not matter.", "frame": "Order ___ matter, so I count ___.", "cards": [{"h": "Does order matter?", "big": "8 runners.", "steps": ["Gold, silver, bronze: ⟨8 \\cdot 7 \\cdot 6 = {{336}}⟩", "Any 3 to advance: ⟨\\frac{336}{3!} = {{56}}⟩", "⟨5! = {{120}}⟩"]}]};
  N["data-analysis-probability-skill-07"] = {"obj": "find experimental probabilities, compare them with theoretical ones and design simulations", "idea": "Experimental probability is the fraction of trials in which the event happened. With more trials it tends to get closer to the theoretical probability. A simulation models a chance situation with a tool such as random numbers.", "voc": [["experimental probability", "The number of times an event happens ÷ the number of trials."], ["simulation", "A model of a chance situation using coins, cubes, spinners or random numbers."], ["trial", "One repetition of an experiment."]], "watch": "Expecting a small number of trials to match the theoretical probability exactly.", "frame": "The event happened ___ times in ___ trials, so the experimental probability is ___.", "cards": [{"h": "Experiment and simulate", "big": "A free throw is made 70% of the time.", "steps": ["In 50 trials, 32 makes: ⟨\\frac{32}{50} = {{64}}\\%⟩", "Simulate with digits 0–9: let 0–6 be a {{make}}.", "More trials should bring the result closer to {{70%}}."]}]};
  N["data-analysis-probability-skill-08"] = {"obj": "choose representative samples and use them to make predictions about a population", "idea": "A random sample gives every member of the population an equal chance, so it tends to be representative. Use the sample proportion to predict for the population, and expect variation between samples.", "voc": [["population", "The whole group you want to know about."], ["sample", "Part of the population that is studied."], ["random sample", "A sample in which every member has an equal chance of being chosen."], ["inference", "A conclusion about a population drawn from a sample."]], "watch": "Trusting a convenience sample (friends, one class, volunteers) to represent everyone.", "frame": "The sample is (not) representative because ___. I predict ___.", "cards": [{"h": "Predict from a sample", "big": "60 random students: 21 prefer pizza. The school has 900 students.", "steps": ["Sample rate: ⟨\\frac{21}{60} = {{35}}\\%⟩", "Prediction: ⟨0.35 \\times 900 = {{315}}⟩", "Asking only the soccer team would be {{biased}}."]}]};
  N["data-analysis-probability-skill-09"] = {"obj": "compare two populations using measures of center and variability", "idea": "Compare two groups by their centers and spreads. The difference in centers, measured in units of spread (such as the MAD), shows how much the groups overlap.", "voc": [["mean absolute deviation (MAD)", "The average distance of the data values from the mean."], ["overlap", "How much the values of two data sets share the same range."]], "watch": "Comparing only the means and ignoring how spread out the data are.", "frame": "The means differ by ___, which is about ___ MADs, so the overlap is ___.", "cards": [{"h": "Center and spread", "big": "Team A mean 62 in., MAD 2; Team B mean 68 in., MAD 2.", "steps": ["Difference of means: {{6}} in.", "⟨\\frac{6}{2} = {{3}}⟩ MADs", "Large difference, so the groups {{overlap little}}."]}]};
  /* ---------- nonlinear-functions-polynomials ---------- */
  N["nonlinear-functions-polynomials-skill-01"] = {"obj": "identify arithmetic and geometric sequences and write their rules", "idea": "An arithmetic sequence adds the same number each time (common difference); a geometric sequence multiplies by the same number (common ratio).", "voc": [["arithmetic sequence", "A sequence with a common difference between terms."], ["geometric sequence", "A sequence with a common ratio between terms."], ["common ratio", "The number each term is multiplied by to get the next."]], "watch": "Calling a sequence arithmetic because it increases, without checking the differences.", "frame": "Each term is ___ the one before, so the sequence is ___.", "cards": [{"h": "Add or multiply?", "big": "Check differences and ratios.", "steps": ["5, 9, 13, 17: arithmetic, difference {{4}}", "3, 6, 12, 24: geometric, ratio {{2}}", "Next term of 3, 6, 12, 24: {{48}}"]}]};
  N["nonlinear-functions-polynomials-skill-02"] = {"obj": "graph quadratic and other nonlinear functions from tables and recognize them", "idea": "A function is linear only if equal steps in x give equal changes in y. Squares and absolute values make U- and V-shaped graphs that are not straight lines.", "voc": [["nonlinear function", "A function whose graph is not a straight line."], ["parabola", "The U-shaped graph of a quadratic function such as ⟨y = x^2⟩."]], "watch": "Connecting points with straight segments and calling the graph linear.", "frame": "The changes in y are ___, so the function is ___.", "cards": [{"h": "Equal steps?", "big": "Table for ⟨y = x^2 - 1⟩.", "steps": ["x = −2, −1, 0, 1, 2 → y = 3, 0, {{−1}}, 0, 3", "Changes in y: −3, −1, 1, 3, {{not}} equal", "The graph is a {{parabola}}."]}]};
  N["nonlinear-functions-polynomials-skill-03"] = {"obj": "model exponential growth and decay", "idea": "Exponential models multiply by the same factor each period: ⟨y = a \\cdot b^x⟩. Growth has b > 1; decay has 0 < b < 1. A growth rate r gives b = 1 + r.", "voc": [["exponential growth", "An increase by the same percent each period; b > 1."], ["exponential decay", "A decrease by the same percent each period; 0 < b < 1."], ["growth factor", "The number b that the amount is multiplied by each period."]], "watch": "Adding the rate each period (linear) instead of multiplying by the factor.", "frame": "The amount is multiplied by ___ each ___, so the model is ___.", "cards": [{"h": "Multiply each period", "big": "Population 500 grows 10% a year.", "steps": ["⟨y = 500(1.1)^x⟩", "After 2 years: ⟨500(1.21) = {{605}}⟩", "A car worth $20,000 loses 15% a year: ⟨y = 20000({{0.85}})^x⟩"]}]};
  N["nonlinear-functions-polynomials-skill-04"] = {"obj": "classify polynomials and write them in standard form", "idea": "A polynomial is a sum of monomials. Standard form lists terms from highest to lowest degree; name it by its degree and its number of terms.", "voc": [["monomial", "A number, a variable, or a product of numbers and variables with whole-number exponents."], ["degree", "The greatest exponent of the variable in a polynomial."], ["binomial / trinomial", "A polynomial with two terms / three terms."]], "watch": "Finding the degree from the first term written instead of the greatest exponent.", "frame": "The degree is ___ and there are ___ terms, so it is a ___.", "cards": [{"h": "Standard form", "big": "Rewrite ⟨4 + 3x^2 - 7x^3⟩.", "steps": ["⟨-7x^3 + 3x^2 + {{4}}⟩", "Degree: {{3}}", "Three terms: a cubic {{trinomial}}"]}]};
  N["nonlinear-functions-polynomials-skill-05"] = {"obj": "add and subtract polynomials", "idea": "Add polynomials by combining like terms. To subtract, add the opposite of every term of the second polynomial.", "voc": [["like terms", "Terms with the same variables raised to the same powers."], ["opposite of a polynomial", "The polynomial with every term’s sign changed."]], "watch": "Changing the sign of only the first term when subtracting.", "frame": "I change the sign of every term in ___ and combine ___.", "cards": [{"h": "Combine like terms", "big": "Subtract ⟨(5x^2 + 2x - 3) - (2x^2 - 4x + 1)⟩.", "steps": ["⟨= 5x^2 + 2x - 3 - 2x^2 + {{4x}} - 1⟩", "⟨= {{3x^2 + 6x - 4}}⟩", "Add ⟨(x^2 + 1) + (3x^2 - 5) = {{4x^2 - 4}}⟩"]}]};
  N["nonlinear-functions-polynomials-skill-06"] = {"obj": "multiply a polynomial by a monomial and factor out a common monomial", "idea": "Use the distributive property: multiply the monomial by every term, adding exponents of like bases. Factoring reverses this by taking out the GCF.", "voc": [["monomial", "A single term such as ⟨3x^2⟩."], ["greatest common factor", "The greatest monomial that divides every term."]], "watch": "Multiplying only the first term, or multiplying the exponents.", "frame": "I multiply ___ by each term: ___.", "cards": [{"h": "Distribute the monomial", "big": "Multiply ⟨3x(2x^2 - 5x + 4)⟩.", "steps": ["⟨= 6x^3 - {{15x^2}} + 12x⟩", "Factor ⟨8x^3 + 12x^2⟩: GCF {{4x^2}}", "⟨= 4x^2(2x + {{3}})⟩"]}]};
